-- Lote 3/4: 25 questões difíceis por obra (50 no total).
WITH incoming AS (
  SELECT * FROM jsonb_to_recordset($questions$[{"book":"livro_espiritos","statement":"A resposta à questão 27 apresenta dois elementos gerais do Universo além de Deus. Quais são eles?","option_a":"Espírito e matéria.","option_b":"Perispírito e princípio vital.","option_c":"Espaço e tempo.","option_d":"Energia e movimento.","option_e":"Corpo e alma.","correct_option":"A","explanation":"A questão 27 identifica Espírito e matéria como elementos gerais do Universo, tendo Deus como princípio de tudo.","reference":"O Livro dos Espíritos, Livro Primeiro, cap. II, questão 27.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Como a obra concilia a existência de mundos materiais com a diversidade de condições espirituais?","option_a":"Todos os mundos são idênticos e destinados aos mesmos Espíritos.","option_b":"Os mundos existem apenas como estados mentais.","option_c":"Os diferentes mundos oferecem condições variadas, adequadas ao grau de adiantamento dos Espíritos.","option_d":"Apenas a Terra possui vida e finalidade espiritual.","option_e":"A condição moral não tem relação com o mundo habitado.","correct_option":"C","explanation":"O capítulo sobre pluralidade dos mundos relaciona as condições de cada mundo ao estágio evolutivo de seus habitantes.","reference":"O Livro dos Espíritos, Livro Primeiro, cap. III, questões 55–58.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Na explicação da escala espírita, qual distinção fundamental separa os Espíritos imperfeitos dos bons Espíritos?","option_a":"A aparência do perispírito.","option_b":"A predominância da influência da matéria, das paixões e das imperfeições morais.","option_c":"O local geográfico onde viveram.","option_d":"A quantidade de conhecimento científico.","option_e":"A capacidade de se comunicar com médiuns.","correct_option":"B","explanation":"A escala considera principalmente o grau de desenvolvimento moral e o afastamento das imperfeições.","reference":"O Livro dos Espíritos, Livro Segundo, cap. I, questões 100–107.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Por que a obra rejeita a ideia de que anjos e demônios sejam categorias criadas sem relação com o progresso?","option_a":"Porque todos os Espíritos são idênticos em evolução.","option_b":"Porque anjos e demônios seriam apenas símbolos literários.","option_c":"Porque os Espíritos não possuem liberdade.","option_d":"Porque os seres espirituais progridem e as diferenças decorrem de seu estado moral, não de uma criação essencialmente distinta.","option_e":"Porque não existe mundo espiritual.","correct_option":"D","explanation":"A obra interpreta os chamados anjos e demônios à luz da origem comum e da progressão dos Espíritos.","reference":"O Livro dos Espíritos, Livro Segundo, cap. I, questões 128–131.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Como a justiça da reencarnação é fundamentada na obra?","option_a":"Oferecendo novas oportunidades de progresso e reparação em condições diversas.","option_b":"Condenando o Espírito a repetir eternamente os mesmos erros.","option_c":"Garantindo que todos tenham experiências idênticas.","option_d":"Eliminando a responsabilidade individual.","option_e":"Distribuindo privilégios sem relação com as escolhas.","correct_option":"A","explanation":"A pluralidade das existências é apresentada como expressão da justiça e da bondade divinas, permitindo progresso gradual.","reference":"O Livro dos Espíritos, Livro Segundo, cap. IV, questão 171.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Qual é a implicação doutrinária da questão 459 sobre a influência dos Espíritos?","option_a":"Toda decisão humana é determinada por desencarnados.","option_b":"A influência espiritual é impossível.","option_c":"Os Espíritos podem influenciar pensamentos e atos, mas isso não elimina o discernimento e a responsabilidade individual.","option_d":"Somente Espíritos superiores influenciam encarnados.","option_e":"A influência só ocorre em manifestações ostensivas.","correct_option":"C","explanation":"A obra afirma a influência espiritual, mas não a transforma em determinismo absoluto.","reference":"O Livro dos Espíritos, Livro Segundo, cap. IX, questão 459.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Por que a obra considera que a escolha das provas não equivale a escolher arbitrariamente todos os acontecimentos?","option_a":"Porque o Espírito encarnado não tem qualquer passado.","option_b":"Porque a escolha se relaciona a necessidades de progresso e ocorre conforme o grau de compreensão do Espírito.","option_c":"Porque os pais escolhem todas as provas dos filhos.","option_d":"Porque as provas são definidas exclusivamente por governos espirituais.","option_e":"Porque a liberdade deixa de existir antes da encarnação.","correct_option":"B","explanation":"A escolha das provas é descrita dentro de limites morais e de compreensão, visando ao progresso, e não como controle absoluto de cada detalhe.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VI, questões 258–273.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Qual é a relação entre perturbação espiritual após a morte e o grau de apego à vida material?","option_a":"A perturbação é sempre igual para todos.","option_b":"O apego não interfere na transição.","option_c":"A perturbação é necessariamente eterna.","option_d":"A transição pode variar conforme as condições do Espírito, seus hábitos, a consciência e o apego à matéria.","option_e":"A perturbação depende somente da idade física.","correct_option":"D","explanation":"O capítulo sobre retorno à vida espiritual descreve diferenças na perturbação conforme a condição moral e os vínculos do Espírito.","reference":"O Livro dos Espíritos, Livro Segundo, cap. III, questões 163–165.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Como a obra explica a afinidade entre Espíritos?","option_a":"Pela semelhança de tendências, sentimentos e grau de adiantamento.","option_b":"Pela proximidade física durante a última encarnação, exclusivamente.","option_c":"Pela riqueza acumulada em vida.","option_d":"Pelo parentesco sanguíneo apenas.","option_e":"Pela aparência do corpo anterior.","correct_option":"A","explanation":"As relações espirituais são influenciadas por simpatias e afinidades morais, não apenas por vínculos físicos.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VI, questões 291–303.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Qual é a função do esquecimento do passado na construção de relações familiares atuais?","option_a":"Impedir toda reconciliação.","option_b":"Garantir que antigos desafetos se reconheçam imediatamente.","option_c":"Permitir que os vínculos atuais sejam vividos com liberdade e novas oportunidades de reconciliação, sem a influência direta das lembranças.","option_d":"Eliminar os compromissos morais anteriores.","option_e":"Tornar os laços afetivos irrelevantes.","correct_option":"C","explanation":"O esquecimento favorece novas relações e experiências, sem expor continuamente as lembranças de conflitos passados.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VII, questões 392–399.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Qual é a diferença entre instinto e inteligência na análise da obra?","option_a":"O instinto é sempre consciente e calculado.","option_b":"A inteligência é puramente automática.","option_c":"O instinto é uma faculdade adquirida apenas pela educação.","option_d":"O instinto orienta ações necessárias de modo espontâneo; a inteligência envolve elaboração e escolha.","option_e":"A inteligência existe somente após a encarnação humana.","correct_option":"D","explanation":"O capítulo distingue o instinto, frequentemente espontâneo, da inteligência, embora reconheça relações entre ambos.","reference":"O Livro dos Espíritos, Livro Primeiro, cap. IV, questões 71–75.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Por que a obra considera insuficiente medir o progresso de uma sociedade apenas por suas conquistas materiais?","option_a":"Porque o progresso moral e a justiça nas relações também são necessários para o aperfeiçoamento coletivo.","option_b":"Porque as conquistas materiais são sempre prejudiciais.","option_c":"Porque a civilização deve abandonar a ciência.","option_d":"Porque o progresso intelectual não existe.","option_e":"Porque a legislação não influencia a vida social.","correct_option":"A","explanation":"O capítulo sobre progresso diferencia desenvolvimento material e aperfeiçoamento moral, indicando que um não substitui o outro.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. VIII, questões 780–793.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Como a lei de conservação se relaciona com a lei de destruição?","option_a":"Uma anula completamente a outra.","option_b":"A conservação protege a vida, enquanto a destruição necessária participa da renovação natural; o abuso humano é que deve ser evitado.","option_c":"A destruição é sempre moralmente superior.","option_d":"A conservação exige imobilidade absoluta.","option_e":"Ambas tratam somente da vida espiritual.","correct_option":"B","explanation":"Os capítulos distinguem o instinto de conservação e os processos naturais de transformação, condenando a destruição abusiva.","reference":"O Livro dos Espíritos, Livro Terceiro, caps. V e VI, questões 702–735.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Qual é a crítica moral implícita na questão sobre o duelo?","option_a":"O duelo é aceitável quando há testemunhas.","option_b":"O duelo demonstra coragem e honra.","option_c":"O duelo é uma forma legítima de justiça privada.","option_d":"A defesa da honra não justifica a violência motivada pelo orgulho e pela vaidade.","option_e":"A violência só é condenável quando há morte.","correct_option":"D","explanation":"A obra critica o duelo como expressão de orgulho e apego a convenções humanas que não justificam tirar uma vida.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. VI, questões 757–759.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Como a obra relaciona o progresso das leis humanas ao progresso moral?","option_a":"As leis humanas devem permanecer imutáveis.","option_b":"A legislação não tem relação com a moral.","option_c":"As leis tendem a se aperfeiçoar à medida que a sociedade compreende melhor a justiça e os direitos.","option_d":"O progresso legal depende apenas da força militar.","option_e":"Toda mudança legislativa representa decadência.","correct_option":"C","explanation":"A obra entende que as leis humanas devem acompanhar o progresso e se aproximar da justiça natural.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. VIII, questões 794–797.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Por que a caridade não pode ser reduzida à esmola, segundo a definição da questão 886?","option_a":"Porque envolve também benevolência, indulgência e perdão nas relações cotidianas.","option_b":"Porque a ajuda material nunca é necessária.","option_c":"Porque a caridade é apenas uma virtude privada.","option_d":"Porque o perdão substitui toda responsabilidade.","option_e":"Porque somente instituições podem praticá-la.","correct_option":"A","explanation":"A definição de caridade abrange atitudes e relações morais amplas, indo além da doação material.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. XI, questão 886.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"O que torna a lei natural universal, segundo o capítulo I das leis morais?","option_a":"Sua adoção por todos os governos.","option_b":"Sua origem divina e sua aplicação a todos os seres, independentemente de convenções humanas.","option_c":"Sua publicação em códigos civis.","option_d":"Sua validade somente para os encarnados.","option_e":"Sua adaptação aos interesses individuais.","correct_option":"B","explanation":"A lei natural é apresentada como lei de Deus, universal e independente das convenções sociais.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. I, questões 614–617.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Qual é o papel do arrependimento na perspectiva do progresso espiritual?","option_a":"Apaga automaticamente todas as consequências dos atos.","option_b":"Só tem valor quando é público.","option_c":"É inútil depois da morte.","option_d":"Marca o reconhecimento do erro e pode iniciar a mudança, mas deve ser acompanhado de reparação e esforço.","option_e":"Substitui a prática do bem.","correct_option":"D","explanation":"O arrependimento é um primeiro passo para a transformação, mas não dispensa o esforço de reparar e progredir.","reference":"O Livro dos Espíritos, Livro Quarto, cap. II, questões 990–1002.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Por que a obra considera a felicidade relativa ao grau de adiantamento do Espírito?","option_a":"Porque as necessidades e fontes de satisfação se transformam conforme o desenvolvimento moral.","option_b":"Porque todos os Espíritos possuem as mesmas aspirações materiais.","option_c":"Porque a felicidade depende exclusivamente de riqueza.","option_d":"Porque o progresso elimina toda experiência afetiva.","option_e":"Porque a felicidade é determinada pelo corpo físico.","correct_option":"A","explanation":"A obra relaciona a felicidade ao estado moral e às necessidades espirituais, que se modificam com o progresso.","reference":"O Livro dos Espíritos, Livro Quarto, cap. II, questões 967–982.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Como a influência do organismo é tratada em relação às faculdades do Espírito?","option_a":"O corpo cria integralmente o Espírito.","option_b":"O organismo não exerce qualquer influência durante a encarnação.","option_c":"As condições orgânicas podem limitar a manifestação das faculdades, sem serem a origem do Espírito.","option_d":"A inteligência é determinada apenas pela hereditariedade.","option_e":"O Espírito deixa de existir quando o corpo adoece.","correct_option":"C","explanation":"A obra distingue o Espírito de sua manifestação por meio do organismo, reconhecendo limitações corporais.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VII, questões 367–370.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Qual é a consequência ética da ideia de que todos os Espíritos têm origem comum e destino de progresso?","option_a":"A legitimação de castas espirituais permanentes.","option_b":"A indiferença diante do sofrimento alheio.","option_c":"A superioridade moral automática dos mais instruídos.","option_d":"A impossibilidade de mudança pessoal.","option_e":"O reconhecimento da fraternidade e da possibilidade de aperfeiçoamento de todos.","correct_option":"E","explanation":"A origem comum e a destinação ao progresso fundamentam uma visão de fraternidade e responsabilidade recíproca.","reference":"O Livro dos Espíritos, Livro Segundo, cap. I, questões 115–118; Livro Terceiro, cap. XI.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Como a obra articula liberdade, educação e progresso moral?","option_a":"A educação elimina o livre-arbítrio.","option_b":"O desenvolvimento do discernimento favorece escolhas mais conscientes, sem abolir a liberdade.","option_c":"A liberdade depende da ausência de conhecimento.","option_d":"A moral é imposta exclusivamente pelo organismo.","option_e":"O progresso moral ocorre sem participação individual.","correct_option":"B","explanation":"A educação e o esclarecimento ajudam o Espírito a exercer melhor sua liberdade e assumir responsabilidade por suas decisões.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. VIII, questões 780–785.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Qual é a razão doutrinária para não interpretar toda dificuldade como punição específica?","option_a":"Porque a obra nega qualquer relação entre causa e efeito.","option_b":"Porque somente os Espíritos podem sofrer.","option_c":"Porque as provas podem ter diferentes funções e origens, e o julgamento da situação alheia excede nosso conhecimento.","option_d":"Porque a justiça divina não existe.","option_e":"Porque todo sofrimento é escolhido conscientemente em todos os detalhes.","correct_option":"C","explanation":"A obra trata de provas, expiações e causas diversas, mas não autoriza identificar de fora a causa exata de cada sofrimento.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VI, questões 258–273; Livro Terceiro, cap. I.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"O que a obra sugere sobre a relação entre intenção e mérito na prática do bem?","option_a":"O mérito depende apenas do resultado visível.","option_b":"A intenção é irrelevante se houver reconhecimento público.","option_c":"A intenção substitui toda ação concreta.","option_d":"O valor moral considera a intenção sincera e o esforço real, não apenas a aparência do ato.","option_e":"O mérito depende da posição social.","correct_option":"D","explanation":"A avaliação moral não se limita ao resultado externo; considera a intenção e o esforço de fazer o bem.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. X, questões 629–646.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Qual é a consequência do controle universal do ensino dos Espíritos para a autoridade doutrinária?","option_a":"A autoridade fica vinculada à concordância ampla e independente, submetida também ao exame da razão.","option_b":"A autoridade passa a depender do médium mais conhecido.","option_c":"Toda comunicação individual torna-se infalível.","option_d":"A tradição de um único grupo é suficiente.","option_e":"A razão deve ser afastada para preservar a fé.","correct_option":"A","explanation":"A introdução apresenta a concordância independente como garantia, sem dispensar o exame racional.","reference":"O Evangelho Segundo o Espiritismo, Introdução, seção II.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Por que a introdução considera importante que os ensinamentos sejam transmitidos em diferentes lugares e por médiuns sem relação entre si?","option_a":"Para criar uma autoridade central.","option_b":"Para impedir qualquer comparação de mensagens.","option_c":"Para reduzir a possibilidade de influência pessoal ou local e verificar a concordância dos princípios.","option_d":"Para privilegiar médiuns anônimos por si só.","option_e":"Para substituir o estudo das obras.","correct_option":"C","explanation":"A diversidade de origens é apresentada como salvaguarda contra sistemas pessoais e influências particulares.","reference":"O Evangelho Segundo o Espiritismo, Introdução, seção II.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Como o capítulo I diferencia a lei divina da legislação mosaica?","option_a":"Afirma que ambas são idênticas em todos os detalhes.","option_b":"Distingue os princípios divinos permanentes das disposições humanas e circunstanciais da legislação antiga.","option_c":"Rejeita todo ensinamento anterior a Jesus.","option_d":"Considera a lei divina uma criação política.","option_e":"Afirma que a moral depende apenas de costumes locais.","correct_option":"B","explanation":"O capítulo explica que Jesus não destrói a lei divina, mas esclarece seu sentido e supera interpretações e prescrições humanas circunstanciais.","reference":"O Evangelho Segundo o Espiritismo, cap. I, itens 1–3.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Qual é o argumento central do capítulo III ao relacionar mundos e progresso espiritual?","option_a":"Todos os mundos são moradas de Espíritos no mesmo estágio.","option_b":"A Terra é o único mundo com finalidade moral.","option_c":"Os mundos mais felizes não possuem vida espiritual.","option_d":"As condições dos mundos variam e se relacionam ao adiantamento moral de seus habitantes.","option_e":"A evolução espiritual ocorre sem relação com as condições de existência.","correct_option":"D","explanation":"O capítulo apresenta uma pluralidade de mundos com condições distintas, compatíveis com diferentes graus de progresso.","reference":"O Evangelho Segundo o Espiritismo, cap. III, itens 3–5.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Como o capítulo IV utiliza o diálogo de Jesus com Nicodemos para fundamentar a reencarnação?","option_a":"Interpreta o novo nascimento como retorno do Espírito à vida corporal, distinguindo-o do nascimento físico inicial.","option_b":"Entende o novo nascimento como mudança de nacionalidade.","option_c":"Reduz a passagem a uma metáfora sem consequência doutrinária.","option_d":"Afirma que o corpo ressuscita exatamente como era.","option_e":"Associa o novo nascimento apenas ao batismo ritual.","correct_option":"A","explanation":"O capítulo interpreta o diálogo como referência à necessidade de renascimento corporal e à pluralidade das existências.","reference":"O Evangelho Segundo o Espiritismo, cap. IV, itens 4–17.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Qual é a função moral da explicação sobre causas anteriores das aflições?","option_a":"Autorizar que se culpe quem sofre.","option_b":"Substituir a assistência concreta por especulação.","option_c":"Oferecer uma perspectiva de justiça e continuidade da vida, sem dispensar compaixão e auxílio.","option_d":"Provar que toda dor é merecida.","option_e":"Eliminar a responsabilidade coletiva diante da injustiça.","correct_option":"C","explanation":"A explicação amplia a compreensão da vida, mas o capítulo mantém a necessidade de solidariedade e resignação ativa.","reference":"O Evangelho Segundo o Espiritismo, cap. V, itens 4–13.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Como o capítulo VI articula consolação e responsabilidade moral?","option_a":"A consolação dispensa mudança de conduta.","option_b":"O consolo espiritual fortalece a esperança e chama à vivência dos ensinamentos de Jesus.","option_c":"A esperança deve ser exclusivamente material.","option_d":"O Consolador elimina as provas da vida.","option_e":"A responsabilidade moral é transferida aos Espíritos.","correct_option":"B","explanation":"O capítulo apresenta o Consolador como esclarecimento e amparo que também convida à transformação moral.","reference":"O Evangelho Segundo o Espiritismo, cap. VI, itens 3–8.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Qual é a crítica do capítulo VII à inteligência desacompanhada de humildade?","option_a":"A inteligência é sempre um defeito.","option_b":"O estudo deve ser abandonado.","option_c":"A humildade é sinal de ignorância.","option_d":"O orgulho intelectual fecha o indivíduo ao aprendizado e à verdade.","option_e":"O conhecimento torna impossível a caridade.","correct_option":"D","explanation":"O capítulo associa a pobreza de espírito à humildade e critica a presunção de quem se julga superior.","reference":"O Evangelho Segundo o Espiritismo, cap. VII, itens 1–2.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Como o capítulo IX distingue mansidão de fraqueza moral?","option_a":"A mansidão é domínio de si e rejeição da violência, não submissão ao erro ou abandono do dever.","option_b":"A mansidão exige aceitar toda injustiça.","option_c":"A mansidão proíbe qualquer posicionamento firme.","option_d":"A fraqueza é apresentada como virtude.","option_e":"A paz depende de evitar toda responsabilidade.","correct_option":"A","explanation":"A mansidão é uma virtude ativa de domínio próprio e respeito, não uma autorização para omissão diante do mal.","reference":"O Evangelho Segundo o Espiritismo, cap. IX, itens 1–6.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Qual é a relação entre indulgência e justiça no capítulo X?","option_a":"Indulgência significa negar que existam erros.","option_b":"Justiça exige condenação pública em todos os casos.","option_c":"Indulgência significa compreender as limitações alheias, sem abandonar a proteção e a responsabilidade.","option_d":"Perdoar significa aprovar a conduta errada.","option_e":"A indulgência deve ser aplicada apenas aos amigos.","correct_option":"C","explanation":"O capítulo recomenda indulgência e autocrítica, sem confundir perdão com aprovação ou negligência.","reference":"O Evangelho Segundo o Espiritismo, cap. X, itens 11–13.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Por que o capítulo XI considera o amor ao próximo um critério universal de conduta?","option_a":"Porque depende da identidade religiosa de cada pessoa.","option_b":"Porque se limita às relações familiares.","option_c":"Porque substitui a justiça por emoção.","option_d":"Porque fundamenta relações de fraternidade, respeito e responsabilidade para com todos.","option_e":"Porque exige concordância intelectual entre todos.","correct_option":"D","explanation":"O capítulo apresenta o amor ao próximo como princípio que orienta relações sociais e supera divisões particulares.","reference":"O Evangelho Segundo o Espiritismo, cap. XI, itens 1–4.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Como o capítulo XII propõe responder a uma ofensa sem perpetuar o mal?","option_a":"Com vingança proporcional.","option_b":"Com domínio das paixões, perdão e desejo sincero de que o outro se transforme.","option_c":"Com humilhação pública do ofensor.","option_d":"Com indiferença a qualquer sofrimento.","option_e":"Com retaliação indireta.","correct_option":"B","explanation":"Amar os inimigos implica romper o ciclo de ódio e vingança, sem chamar o mal de bem.","reference":"O Evangelho Segundo o Espiritismo, cap. XII, itens 1–3.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Qual é a distinção entre caridade material e caridade moral no capítulo XIII?","option_a":"A caridade moral é sempre superior e torna a material desnecessária.","option_b":"A caridade material é a única verdadeira.","option_c":"A caridade moral inclui benevolência, paciência, indulgência e respeito, podendo acompanhar a ajuda material.","option_d":"A caridade material deve ser feita com publicidade.","option_e":"As duas formas são incompatíveis.","correct_option":"C","explanation":"O capítulo amplia a noção de caridade para incluir atitudes morais cotidianas, além da assistência material.","reference":"O Evangelho Segundo o Espiritismo, cap. XIII, itens 9–10.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Como o capítulo XIV aborda conflitos entre deveres familiares e progresso moral?","option_a":"Determina obediência cega a qualquer ordem familiar.","option_b":"Afirma que os laços de sangue anulam todos os demais deveres.","option_c":"Considera a família sem importância espiritual.","option_d":"Reconhece os deveres de respeito e cuidado, mas distingue vínculos corporais de afinidades e compromissos espirituais.","option_e":"Proíbe relações afetivas fora da família biológica.","correct_option":"D","explanation":"O capítulo analisa os deveres familiares e a distinção entre família corporal e espiritual, sem reduzir o amor a obediência cega.","reference":"O Evangelho Segundo o Espiritismo, cap. XIV, itens 1–9.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Por que o capítulo XV coloca a caridade acima de sinais exteriores de pertencimento religioso?","option_a":"Porque o valor moral se revela na prática do bem, não apenas em rótulos ou formalidades.","option_b":"Porque toda religião é considerada inútil.","option_c":"Porque a intenção não importa.","option_d":"Porque a caridade é uma cerimônia.","option_e":"Porque a conduta não tem relação com a vida futura.","correct_option":"A","explanation":"O capítulo sintetiza a salvação na caridade vivida, em vez de privilégios de grupo ou sinais externos.","reference":"O Evangelho Segundo o Espiritismo, cap. XV, itens 1–5.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Qual é o dilema moral apresentado pela figura de Mamon no capítulo XVI?","option_a":"Escolher entre estudo e trabalho.","option_b":"Escolher entre vida familiar e vida social.","option_c":"Permitir que o apego à riqueza governe a vida ou utilizar os recursos sem se tornar escravo deles.","option_d":"Escolher entre fé e caridade.","option_e":"Escolher entre pobreza e conhecimento.","correct_option":"C","explanation":"O capítulo alerta para a submissão aos bens materiais e incentiva o uso responsável da riqueza.","reference":"O Evangelho Segundo o Espiritismo, cap. XVI, itens 1–3.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Como o capítulo XVII interpreta a perfeição moral em relação à vida cotidiana?","option_a":"Como um estado reservado a quem se afasta da sociedade.","option_b":"Como esforço contínuo de virtude, caridade e domínio das próprias imperfeições nas relações diárias.","option_c":"Como ausência completa de dificuldades externas.","option_d":"Como conhecimento teórico sem ação.","option_e":"Como conquista imediata por declaração de fé.","correct_option":"B","explanation":"A perfeição moral é apresentada como direção prática de transformação, expressa em atitudes e relações.","reference":"O Evangelho Segundo o Espiritismo, cap. XVII, itens 1–4.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Qual é a implicação da parábola do semeador para a responsabilidade de quem recebe ensinamentos?","option_a":"A responsabilidade pertence apenas a quem ensina.","option_b":"A mensagem produz o mesmo efeito em qualquer disposição.","option_c":"O resultado depende exclusivamente do ambiente.","option_d":"A receptividade, a compreensão e a perseverança influenciam o fruto do ensinamento.","option_e":"O estudo não interfere na transformação.","correct_option":"D","explanation":"A parábola destaca que o ensinamento precisa encontrar disposição e continuidade para produzir frutos.","reference":"O Evangelho Segundo o Espiritismo, cap. XVIII, item 1.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Como o capítulo XIX diferencia fé verdadeira de credulidade?","option_a":"A fé verdadeira pode ser raciocinada e acompanhada de confiança ativa, não de aceitação irrefletida.","option_b":"A credulidade é sempre mais elevada.","option_c":"A fé verdadeira proíbe questionamentos.","option_d":"A razão deve ser abandonada.","option_e":"A fé depende de fenômenos extraordinários.","correct_option":"A","explanation":"O capítulo valoriza a fé que enfrenta a razão e sustenta a ação, distinguindo-a da crença sem exame.","reference":"O Evangelho Segundo o Espiritismo, cap. XIX, itens 6–7.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Qual é a interpretação moral da parábola dos trabalhadores da última hora quanto à justiça divina?","option_a":"A recompensa depende somente da duração do serviço.","option_b":"Os últimos são sempre superiores aos primeiros.","option_c":"A misericórdia divina considera a disposição sincera e o trabalho no bem, sem reduzir tudo ao tempo cronológico.","option_d":"O trabalho tardio é inútil.","option_e":"A parábola condena quem começou cedo.","correct_option":"C","explanation":"O capítulo destaca a bondade e a justiça divinas, valorizando a sinceridade e a disposição para servir.","reference":"O Evangelho Segundo o Espiritismo, cap. XX, itens 1–3.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Por que o capítulo XXI recomenda cautela diante de manifestações e discursos extraordinários?","option_a":"Porque todo fenômeno espiritual é necessariamente falso.","option_b":"Porque a aparência impressionante não garante elevação; os frutos morais e a coerência devem ser examinados.","option_c":"Porque somente a autoridade institucional decide a verdade.","option_d":"Porque a razão não pode avaliar ensinamentos.","option_e":"Porque a popularidade é prova suficiente.","correct_option":"B","explanation":"O capítulo alerta contra falsos profetas e orienta a avaliar o conteúdo e os resultados morais de seus ensinamentos.","reference":"O Evangelho Segundo o Espiritismo, cap. XXI, itens 1–3.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Qual é o princípio de responsabilidade implícito no capítulo XXV sobre pedir e buscar?","option_a":"A providência substitui todo esforço humano.","option_b":"O pedido correto deve sempre ser atendido literalmente.","option_c":"A busca deve ser apenas interior e sem ação.","option_d":"A confiança na providência deve coexistir com iniciativa, trabalho e perseverança.","option_e":"A pessoa deve esperar sem agir.","correct_option":"D","explanation":"O capítulo interpreta a busca como esforço ativo, compatível com a confiança na providência divina.","reference":"O Evangelho Segundo o Espiritismo, cap. XXV, itens 1–5.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Como o capítulo XXVI aplica o princípio da gratuidade aos dons espirituais?","option_a":"Os dons devem ser usados para benefício pessoal exclusivo.","option_b":"A mediunidade deve ser convertida em fonte de lucro.","option_c":"O serviço espiritual deve ser reservado aos que podem pagar.","option_d":"Os dons recebidos gratuitamente devem ser colocados a serviço do bem sem exploração comercial.","option_e":"A gratuidade impede qualquer responsabilidade do médium.","correct_option":"D","explanation":"O capítulo condena a comercialização dos dons espirituais e destaca seu uso desinteressado.","reference":"O Evangelho Segundo o Espiritismo, cap. XXVI, itens 1–2.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Qual é a relação entre prece e ação moral no capítulo XXVII?","option_a":"A prece fortalece a disposição para o bem, mas não substitui o dever de agir e melhorar-se.","option_b":"A prece dispensa o trabalho.","option_c":"A prece garante que terceiros mudem de vontade.","option_d":"A prece elimina as consequências de escolhas.","option_e":"A prece é útil somente quando pública.","correct_option":"A","explanation":"A obra apresenta a prece como recurso de elevação e auxílio, integrado à responsabilidade e à ação pessoal.","reference":"O Evangelho Segundo o Espiritismo, cap. XXVII, itens 1–4.","difficulty":"dificil","active":true}]$questions$::jsonb)
  AS x(book text, statement text, option_a text, option_b text, option_c text, option_d text, option_e text, correct_option text, explanation text, reference text, difficulty text, active boolean)
)
INSERT INTO public.questions (book, statement, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, reference, difficulty, active)
